Minimal reproducible example
import FontAwesome from "@expo/vector-icons/FontAwesome";
import { useFonts } from "expo-font";
import { SplashScreen, Stack } from "expo-router";
import { Text, NativeBaseProvider } from "native-base";
import { useEffect } from "react";
import theme from "~/components/theme";
import { AuthProvider } from "~/providers/AuthProvider";

export {
  // Catch any errors thrown by the Layout component.
  ErrorBoundary,
} from "expo-router";

export const unstable_settings = {
  // Ensure that reloading on `/modal` keeps a back button present.
  initialRouteName: "(tabs)",
};

export default function RootLayout() {
  const [loaded, error] = useFonts({
    SpaceMono: require("../assets/fonts/SpaceMono-Regular.ttf"),
    ...FontAwesome.font,
  });

  // Expo Router uses Error Boundaries to catch errors in the navigation tree.
  useEffect(() => {
    if (error) throw error;
  }, [error]);

  return (
    <NativeBaseProvider theme={theme}>
        <AuthProvider>
          {!loaded && (
            <>
              <Text>splash</Text>
              <SplashScreen />
            </>
          )}
          {loaded && <RootLayoutNav />}
        </AuthProvider>
    </NativeBaseProvider>
  );
}

function RootLayoutNav() {
  // TODO: show splash screen while making sure auth token is valid and loading user info
  return (
    <Stack>
      <Stack.Screen name="(tabs)" options={{ headerShown: false }} />
      <Stack.Screen
        name="(auth)/signin"
        options={{
          headerTitle: "Sign In",
          headerShown: true,
        }}
      />
      <Stack.Screen
        name="(auth)/signup"
        options={{
          headerTitle: "Sign Up",
          headerShown: true,
        }}
      />
      <Stack.Screen name="modal" options={{ presentation: "modal" }} />
    </Stack>
  );
}
// import { useQuery, gql } from "@apollo/client";
// import * as SecureStore from "expo-secure-store";
import { useRouter, useSegments } from "expo-router";
import React from "react";

interface AuthContextType {
  signIn: (id: number) => void;
  signOut: () => void;
  user: User | null;
}

interface User {
  id: number;
}

const AuthContext = React.createContext<AuthContextType | null>(null);

// This hook can be used to access the user info.
export function useAuth() {
  return React.useContext(AuthContext);
}

// This hook will protect the route access based on user authentication.
function useProtectedRoute(user: User | null) {
  const segments = useSegments();
  const router = useRouter();

  React.useEffect(() => {
    const inAuthGroup = segments[0] === "(auth)";

    if (
      // If the user is not signed in and the initial segment is not anything in the auth group.
      !user &&
      !inAuthGroup
    ) {
      // Redirect to the login page.
      router.replace("/(auth)/signup");
    } else if (user && inAuthGroup) {
      // Redirect away from the sign-in page.
      router.replace("/");
    }
  }, [user, segments]);
}

export function AuthProvider(props: React.PropsWithChildren) {
  const [user, setUser] = React.useState<User | null>(null);

  useProtectedRoute(user);

  return (
    <AuthContext.Provider
      value={{
        signIn: (id: number) => setUser({ id }),
        signOut: () => setUser(null),
        user,
      }}
    >
      {props.children}
    </AuthContext.Provider>
  );
}

export default AuthProvider;

Memory leaks do not show where the original allocation occurs
Take the following code:
Box::into_raw(Box::new(5));
which produces the following output with cargo miri run:
The following memory was leaked: alloc1672 (Rust heap, size: 4, align: 4) {
    05 00 00 00                                     │ ....
}

The error message does not mention where the allocation of the memory that has been leaked occurs. A mention of what line the allocates the leaked memory or a backtrace of calls leading up to the allocation would make it significantly easier to figure out what needs to be done to fix the memory leak especially in more complex situations.

Error: data out-of-bounds (length=0, offset=32, code=BUFFER_OVERRUN, version=abi/5.0.7)
I've opened a support ticket before filing this issue.


Issue
It should revert the custom error, works in Remix VM but not with Web3+Truffle in Node.js, tested on a local Ganache network and Avalanche Testnet. Only seems to be able to revert string-based custom errors, if I pass an integer or something that is not a string it gives me the out of bounds error.
Steps to Reproduce
// SPDX-License-Identifier: GPL-3.0
pragma solidity ^0.8.4;


contract TestToken {
    error InsufficientBalance(uint256 withdrawAmount);

    function transfer(uint256 amount) pure public {
        if (amount > 1000)
            revert InsufficientBalance({ withdrawAmount: amount });
    }
}
Expected Behavior
It should revert the custom error, works in Remix VM but not with Web3+Truffle in Node.js, tested on a local Ganache network and Avalanche Testnet. Only seems to be able to revert string-based custom errors, if I pass an integer or something that is not a string it gives me the out of bounds error.
Actual Results
Get the following error in Node.js:
Error: data out-of-bounds (length=0, offset=32, code=BUFFER_OVERRUN, version=abi/5.0.7)

Environment

Operating System: Ubuntu 20.04 LTS
Ethereum client: Ganache/Avalanche
Truffle version (truffle version): "@truffle/hdwallet-provider": "^2.1.8"
node version (node --version): v18.13.0
npm version (npm --version): 8.19.3

Last line of file duplicated on save
When ruff inserts a newline after the imports, it also duplicates the last line in the file. I am using the preview version of ruff in VSCode (0.0.256) on Windows 10. (A quick test shows the same behavior with the release version of 0.0.252.) I have not configured ruff in any way. I have fixAll and organizeImports set to true:
    "[python]": {
        "editor.codeActionsOnSave": {
            "source.fixAll": true,
            "source.organizeImports": true
        }
    }
For example, the first code block below will turn into the second on save (when ruff is enabled):
import datetime

import pandas as pd

def foo(bar: datetime.date) -> pd.DataFrame:
    return pd.DataFrame()
import datetime

import pandas as pd


def foo(bar: datetime.date) -> pd.DataFrame:
    return pd.DataFrame()
    return pd.DataFrame()
If there is no final newline, then the code is formatted into this:
import datetime

import pandas as pd


def foo(bar: datetime.date) -> pd.DataFrame:
    return pd.DataFrame()    return pd.DataFrame()
If the formatter inserts two lines, then the last two lines are duplicated. The first block turns into the second:
import datetime

import pandas as pd
def foo(bar: datetime.date) -> pd.DataFrame:
    return pd.DataFrame()
import datetime

import pandas as pd


def foo(bar: datetime.date) -> pd.DataFrame:
    return pd.DataFrame()
def foo(bar: datetime.date) -> pd.DataFrame:
    return pd.DataFrame()
With ruff disabled, the formatting works correctly.
Please let me know what other information I can provide.

