  frameRate(1);
  str[0] = "0";
  for(int i = 1 ; i < str.length ; i++) {
    str[i] = str[i-1] + String.valueOf(int(random(10)));
  }
  textAlign(RIGHT);

}

void draw() {
  background(0);
  show_text();
}

void show_text() {
  text_size++;
  interligne = floor(text_size * 1.4);
  if(text_size> 20) {
    text_size = 6;
  }

  println(text_size);

  textSize(text_size);
  // textAlign(LEFT); // OK
  textAlign(RIGHT); // KO > problem
  float x = width/2;
  for(int i = 0 ; i < str.length ; i++) {
    text(str[i], x, (i + 1) * interligne);
  }
  stroke(255);
  line(x, 0, x, height);
}

